                mv.visitFieldInsn(PUTSTATIC, cnb.className, Naming.RTTI_FIELD, Naming.RTTI_CONTAINER_DESC);
        }

        @Override
        public String asmName() {
            return Naming.RTTI_FIELD;
        }

        @Override
        public String asmSignature() {
            return Naming.RTTI_CONTAINER_DESC;
        }

    });
